package cn.mop.assetexport;
import cn.mop.domain.DomainException;
import cn.mop.domain.assetimport.AssetImportPrechecker.Column;
import org.apache.poi.ss.usermodel.CellType;
import org.apache.poi.xssf.usermodel.XSSFWorkbook;
import org.junit.jupiter.api.Test;
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.time.Instant;
import java.util.*;
import java.util.zip.*;
import static org.junit.jupiter.api.Assertions.*;
/** Real XLSX bytes and ZIP/XML inspection over explicit synthetic rows, not an authorized export job. */
class AssetLedgerWorkbookTest {
    final UUID tenant=UUID.randomUUID();final Instant generated=Instant.parse("2026-10-04T00:00:00Z");
    EnumMap<Column,String> cells(){var cells=new EnumMap<Column,String>(Column.class);for(Column c:Column.values())cells.put(c,null);return cells;}
    AssetLedgerWorkbook.Row row(Map<Column,String> cells,String status){return new AssetLedgerWorkbook.Row(tenant,UUID.randomUUID(),cells,status);}
    AssetLedgerWorkbook.Encoded encode(List<AssetLedgerWorkbook.Row> rows)throws IOException{return AssetLedgerWorkbook.encode(tenant,rows,true,generated);}
    @Test void emptyKnownSelectionProducesOnlyTheSharedFifteenHeadersPlusOneStatus()throws Exception{try(var template=new XSSFWorkbook(getClass().getResourceAsStream("/asset-import-standard15.xlsx"));var output=new XSSFWorkbook(new ByteArrayInputStream(encode(List.of()).bytes()))){var sheet=output.getSheetAt(0);assertEquals(1,output.getNumberOfSheets());assertEquals(1,sheet.getPhysicalNumberOfRows());assertEquals(16,sheet.getRow(0).getPhysicalNumberOfCells());for(int c=0;c<15;c++)assertEquals(template.getSheetAt(0).getRow(0).getCell(c).getStringCellValue(),sheet.getRow(0).getCell(c).getStringCellValue());assertEquals("维保状态",sheet.getRow(0).getCell(15).getStringCellValue());long expiry=java.util.stream.IntStream.range(0,16).filter(c->sheet.getRow(0).getCell(c).getStringCellValue().equals("维保到期日")).count();assertEquals(1,expiry);}}
    @Test void formulaLookingTextIsStoredAsTextWithoutPrefixingOrExecutingIt()throws Exception{var cells=cells();String[] values={"=1+1","+cmd|' /C synthetic'!A0","-2+3","@SUM(A1:A3)","=HYPERLINK(\"https://example.invalid/\",\"x\")","00000123","<script>synthetic</script>"," leading and trailing ","line1\nline2\tend","\rraw"};for(int i=0;i<values.length;i++)cells.put(Column.values()[i],values[i]);var encoded=encode(List.of(row(cells,null)));try(var workbook=new XSSFWorkbook(new ByteArrayInputStream(encoded.bytes()))){for(int i=0;i<values.length;i++){var cell=workbook.getSheetAt(0).getRow(1).getCell(i);assertEquals(CellType.STRING,cell.getCellType());assertEquals(values[i],cell.getStringCellValue());assertEquals("@",cell.getCellStyle().getDataFormatString());}assertTrue(workbook.getExternalLinksTable().isEmpty());assertTrue(workbook.getSheetAt(0).getHyperlinkList().isEmpty());assertFalse(workbook.isMacroEnabled());}try(var zip=new ZipInputStream(new ByteArrayInputStream(encoded.bytes()))){ZipEntry e;while((e=zip.getNextEntry())!=null){assertFalse(e.getName().endsWith("vbaProject.bin"));String xml=new String(zip.readAllBytes(),StandardCharsets.UTF_8);if(e.getName().startsWith("xl/worksheets/"))assertFalse(xml.matches("(?s).*<f(?:>|\\s).*"));if(e.getName().endsWith(".rels"))assertFalse(xml.contains("TargetMode=\"External\""));}}}
    @Test void explicitUnknownAndEmptyStringRemainDistinctFromZero()throws Exception{var cells=cells();cells.put(Column.NAME,"");cells.put(Column.SERIAL_NUMBER,"0000");try(var workbook=new XSSFWorkbook(new ByteArrayInputStream(encode(List.of(row(cells,null))).bytes()))){var row=workbook.getSheetAt(0).getRow(1);assertEquals(CellType.STRING,row.getCell(0).getCellType());assertEquals("",row.getCell(0).getStringCellValue());assertEquals(CellType.BLANK,row.getCell(1).getCellType());assertEquals("0000",row.getCell(5).getStringCellValue());assertEquals(CellType.BLANK,row.getCell(15).getCellType());}}
    @Test void preservesUnicodeOriginalDatesAndExplicitStatusWithoutInferringCoverage()throws Exception{var cells=cells();cells.put(Column.NAME,"设备😀e\u0301");cells.put(Column.WARRANTY_EXPIRY,"2028-02-29");try(var workbook=new XSSFWorkbook(new ByteArrayInputStream(encode(List.of(row(cells,"未核验"))).bytes()))){var row=workbook.getSheetAt(0).getRow(1);assertEquals("设备😀e\u0301",row.getCell(0).getStringCellValue());assertEquals("2028-02-29",row.getCell(11).getStringCellValue());assertEquals("未核验",row.getCell(15).getStringCellValue());}}
    @Test void foreignTenantFailsBeforeReturningAnyArtifact(){var foreign=new AssetLedgerWorkbook.Row(UUID.randomUUID(),UUID.randomUUID(),cells(),null);assertEquals(404,assertThrows(DomainException.class,()->encode(List.of(row(cells(),null),foreign))).status);}
    @Test void duplicateAssetIdentityDoesNotDuplicateOutputRows(){var row=row(cells(),null);assertEquals(400,assertThrows(DomainException.class,()->encode(List.of(row,row))).status);}
    @Test void missingSelectionCompletionIsNotAnEmptySuccessfulExport(){for(Boolean complete:Arrays.asList(null,false))assertEquals(422,assertThrows(DomainException.class,()->AssetLedgerWorkbook.encode(tenant,List.of(),complete,generated)).status);}
    @Test void incompleteMapsAndNullRowsAreRejected(){var values=cells();values.remove(Column.NOTE);assertThrows(DomainException.class,()->row(values,null));assertThrows(DomainException.class,()->encode(Arrays.asList((AssetLedgerWorkbook.Row)null)));}
    @Test void cellResourceLimitDoesNotTruncateUnicode(){var values=cells();values.put(Column.NOTE,"😀".repeat(2000));assertDoesNotThrow(()->row(values,null));values.put(Column.NOTE,"😀".repeat(2001));assertEquals(413,assertThrows(DomainException.class,()->row(values,null)).status);}
    @Test void xmlInvalidControlAndUnpairedSurrogatesRejectWithoutEchoingText(){for(String value:new String[]{"SYNTHETIC\u0000SECRET","\ud800","\udc00","\ufffe","\uffff"}){var cells=cells();cells.put(Column.NOTE,value);var error=assertThrows(DomainException.class,()->row(cells,null));assertFalse(error.getMessage().contains("SECRET"));}}
    @Test void rowLimitRefusesWholeInputRatherThanSilentlyCuttingIt(){var rows=new ArrayList<AssetLedgerWorkbook.Row>();for(int i=0;i<1001;i++)rows.add(row(cells(),null));assertEquals(413,assertThrows(DomainException.class,()->encode(rows)).status);}
    @Test void aggregateUtf8BudgetRejectsLargeButIndividuallyValidCells(){var rows=new ArrayList<AssetLedgerWorkbook.Row>();for(int n=0;n<100;n++){var cells=cells();for(Column c:Column.values())cells.put(c,"😀".repeat(2000));rows.add(row(cells,null));}assertEquals(413,assertThrows(DomainException.class,()->encode(rows)).status);}
    @Test void maximumRowCountIsRepresentedWithoutHiddenOrDroppedRows()throws Exception{var rows=new ArrayList<AssetLedgerWorkbook.Row>();for(int i=0;i<1000;i++)rows.add(row(cells(),null));var encoded=encode(rows);assertEquals(1000,encoded.dataRows());try(var workbook=new XSSFWorkbook(new ByteArrayInputStream(encoded.bytes()))){assertEquals(1001,workbook.getSheetAt(0).getPhysicalNumberOfRows());assertFalse(workbook.isSheetHidden(0));}}
    @Test void inputMapAndEncodedBytesAreDetached()throws Exception{var values=cells();values.put(Column.NAME,"original");var row=row(values,null);values.put(Column.NAME,"changed");assertEquals("original",row.cells().get(Column.NAME));assertThrows(UnsupportedOperationException.class,()->row.cells().clear());var encoded=encode(List.of(row));byte[] copy=encoded.bytes();copy[0]=0;assertNotEquals(0,encoded.bytes()[0]);assertEquals(HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(encoded.bytes())),encoded.sha256());}
    @Test void sameInputAndExplicitGenerationTimeProduceSameBytesOnPinnedToolchain()throws Exception{var rows=List.of(row(cells(),null));var first=encode(rows);Thread.sleep(1100);var second=encode(rows);assertArrayEquals(first.bytes(),second.bytes());assertEquals(first.sha256(),second.sha256());}
    @Test void metadataNeverClaimsJobPublicationOrAuthorization()throws Exception{var encoded=encode(List.of());assertFalse(encoded.published());assertEquals("CALLER_DECLARATION_ONLY",encoded.selectionVerification());assertEquals("REQUIRED_AT_JOB_AND_DOWNLOAD",encoded.authorizationVerification());try(var workbook=new XSSFWorkbook(new ByteArrayInputStream(encoded.bytes()))){var props=workbook.getProperties();assertEquals("ENCODED_NOT_PUBLISHED",props.getCustomProperties().getProperty("mop.publication_status").getLpwstr());assertEquals(AssetLedgerWorkbook.SCHEMA_VERSION,props.getCustomProperties().getProperty("mop.export_schema").getLpwstr());assertEquals(Date.from(generated),props.getCoreProperties().getCreated());assertEquals(Date.from(generated),props.getCoreProperties().getModified());}}
    @Test void generationTimeAndScopeAreRequiredRatherThanUsingWallClock(){assertThrows(DomainException.class,()->AssetLedgerWorkbook.encode(null,List.of(),true,generated));assertThrows(DomainException.class,()->AssetLedgerWorkbook.encode(tenant,List.of(),true,null));assertThrows(DomainException.class,()->AssetLedgerWorkbook.encode(tenant,List.of(),true,Instant.MAX));}
}
